"""Task 367 candidate — row-cropped detection bank + pad-folded fill conv.

Same 25-template QLinearConv bank as the incumbent (weights bit-identical), but:
- v9 anchor rows cropped 20 -> 18 (pads [2,2,6,6] -> [1,2,5,6]): boxes are never
  vertically clipped (generator: rows = randint(0, height - tall)), and a template
  firing requires its gray top/bottom-wall +1 positions in-grid, so anchors at
  rows 0/19 can provably never fire. v9 10000B -> 9000B.
- fill conv emits [1,1,30,30] directly (pads [4,4,0,0] + Pad  ->  [5,4,11,10]),
  eliminating the separate 900B Pad output, the 400B 20x20 v10, and the 8-param
  pads initializer. All stamps of real firings lie in-grid (a firing requires its
  black-interior +1 positions in-grid), so the folded pad region stays 0.
mem 16200 -> 14800, params 4733 -> 4725, total 20933 -> 19525 (15.05 -> 15.12 pts).
"""
import numpy as np
from onnx import helper
from ._exact import arr_b64, model, tensor


def build(task):
    e4 = np.zeros((1, 10, 1, 1), np.float32)
    e4[0, 4, 0, 0] = 1.0
    inits = [
        tensor('zero_u8', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnfHUxJywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKCksIH0gICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoA')),
        tensor('zero_i8', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnfGkxJywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKCksIH0gICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoA')),
        tensor('q_scale', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnPGY0JywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKCksIH0gICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoAAIA/')),
        tensor('comb_starts', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnPGk4JywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKDMsKSwgfSAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=')),
        tensor('comb_ends', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnPGk4JywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKDMsKSwgfSAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoGAAAAAAAAABQAAAAAAAAAFAAAAAAAAAA=')),
        tensor('comb_axes', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnPGk4JywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKDMsKSwgfSAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoBAAAAAAAAAAIAAAAAAAAAAwAAAAAAAAA=')),
        tensor('comb_steps', arr_b64('k05VTVBZAQB2AHsnZGVzY3InOiAnPGk4JywgJ2ZvcnRyYW5fb3JkZXInOiBGYWxzZSwgJ3NoYXBlJzogKDMsKSwgfSAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIAoFAAAAAAAAAAEAAAAAAAAAAQAAAAAAAAA=')),
        tensor('rect_w', arr_b64('')),
        tensor('rect_b', arr_b64('')),
        tensor('fill_w', arr_b64('')),
        tensor('e4', e4),
    ]
    nodes = [
        helper.make_node('Slice', ['input', 'comb_starts', 'comb_ends', 'comb_axes', 'comb_steps'], ['vslice']),
        helper.make_node('Cast', ['vslice'], ['vc8'], to=2),
        helper.make_node('QLinearConv', ['vc8', 'q_scale', 'zero_u8', 'rect_w', 'q_scale', 'zero_i8', 'q_scale', 'zero_u8', 'rect_b'], ['v9'], kernel_shape=[9, 9], pads=[1, 2, 5, 6]),
        helper.make_node('QLinearConv', ['v9', 'q_scale', 'zero_u8', 'fill_w', 'q_scale', 'zero_u8', 'q_scale', 'zero_u8'], ['v10'], kernel_shape=[5, 5], pads=[5, 4, 11, 10]),
        helper.make_node('Cast', ['v10'], ['cond'], to=9),
        helper.make_node('Where', ['cond', 'e4', 'input'], ['output']),
    ]
    value_infos = [
        helper.make_tensor_value_info('vslice', 1, [1, 2, 20, 20]),
        helper.make_tensor_value_info('vc8', 2, [1, 2, 20, 20]),
        helper.make_tensor_value_info('v9', 2, [1, 25, 18, 20]),
        helper.make_tensor_value_info('v10', 2, [1, 1, 30, 30]),
        helper.make_tensor_value_info('cond', 9, [1, 1, 30, 30]),
    ]
    return model('task367_rowcrop', nodes, inits, output_dtype=1, opset=11, value_infos=value_infos)
